## 9. QR Code Generation in React (`qrcode.react`)

For patient ABHA ID cards and hospital desk scan-and-share:

```tsx
import React, { useRef } from 'react';
import { QRCodeSVG, QRCodeCanvas } from 'qrcode.react';
import { Download } from 'lucide-react';

interface AbhaQrProps {
  abhaNumber: string;
  abhaAddress: string;
  fullName: string;
  gender: string;
  dob: string;
}

export const AbhaQrCard: React.FC<AbhaQrProps> = ({ abhaNumber, abhaAddress, fullName, gender, dob }) => {
  const canvasRef = useRef<HTMLDivElement>(null);

  // ABDM Standardized Scan-and-Share QR payload format
  const qrPayload = JSON.stringify({
    hidn: abhaNumber,
    hid: abhaAddress,
    name: fullName,
    gender: gender,
    dob: dob,
  });

  const downloadQrPng = () => {
    const canvas = canvasRef.current?.querySelector('canvas');
    if (!canvas) return;
    const url = canvas.toDataURL('image/png');
    const a = document.createElement('a');
    a.href = url;
    a.download = `ABHA_QR_${abhaAddress.replace('@', '_')}.png`;
    a.click();
  };

  return (
    <div className="flex flex-col items-center p-6 bg-white rounded-2xl shadow-sm border border-slate-200">
      <div className="p-3 bg-white border border-slate-100 rounded-xl shadow-inner">
        {/* Render responsive vector SVG for crisp UI display */}
        <QRCodeSVG
          value={qrPayload}
          size={200}
          level="H"
          title={`ABHA QR Code for ${fullName}`}
          imageSettings={{
            src: '/abdm-symbol.svg',
            x: undefined,
            y: undefined,
            height: 36,
            width: 36,
            excavate: true,
          }}
        />
      </div>

      {/* Hidden canvas for high-resolution PNG download */}
      <div ref={canvasRef} className="hidden">
        <QRCodeCanvas value={qrPayload} size={600} level="H" />
      </div>

      <button
        onClick={downloadQrPng}
        className="mt-4 inline-flex items-center gap-2 px-4 py-2 text-sm font-medium text-sky-700 bg-sky-50 rounded-lg hover:bg-sky-100 transition-colors"
      >
        <Download className="w-4 h-4" /> Download QR
      </button>
    </div>
  );
};
```

