## 11. Supabase Schema Design Patterns for Health Records (PostgreSQL + RLS)

Below is the production-ready SQL migration pattern conforming to PostgreSQL RLS and FHIR R4:

```sql
-- Enable necessary extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 1. Profiles Table (Linked to Supabase Auth)
CREATE TABLE public.profiles (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  abha_number VARCHAR(17) UNIQUE,       -- Format: 91-XXXX-XXXX-XXXX
  abha_address VARCHAR(100) UNIQUE,     -- Format: name@sbx / name@abdm
  full_name TEXT NOT NULL,
  gender VARCHAR(10) CHECK (gender IN ('MALE', 'FEMALE', 'OTHER')),
  date_of_birth DATE NOT NULL,
  blood_group VARCHAR(5),               -- 'A+', 'B+', 'O+', etc.
  phone_number VARCHAR(15),
  emergency_contact JSONB,             -- { name: "...", relation: "...", phone: "..." }
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Care Contexts (ABDM Encounter representation)
CREATE TABLE public.care_contexts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  patient_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  reference_number VARCHAR(50) NOT NULL, -- e.g., OPD-2026-09-001
  display_name TEXT NOT NULL,           -- e.g., "Consultation with Dr. Sharma"
  facility_name TEXT NOT NULL,          -- e.g., "Apollo Clinics, Bengaluru"
  facility_hfr_id VARCHAR(50),          -- Health Facility Registry ID
  encounter_date TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. Health Records (Prescriptions, Diagnostic Reports, Discharge Summaries)
CREATE TABLE public.health_records (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  patient_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  care_context_id UUID REFERENCES public.care_contexts(id) ON DELETE SET NULL,
  record_type VARCHAR(30) NOT NULL CHECK (
    record_type IN ('PRESCRIPTION', 'DIAGNOSTIC_REPORT', 'DISCHARGE_SUMMARY', 'IMMUNIZATION')
  ),
  title TEXT NOT NULL,
  doctor_name TEXT,
  doctor_registration_no TEXT,          -- e.g., NMC / State council registration
  record_date DATE NOT NULL,
  document_url TEXT,                   -- Supabase storage path
  raw_ocr_text TEXT,                    -- Extracted OCR transcript
  fhir_bundle JSONB NOT NULL DEFAULT '{}'::jsonb, -- NRCeS FHIR R4 Bundle
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. Medications Table (Normalized view of prescription medicines)
CREATE TABLE public.prescriptions_medications (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  record_id UUID NOT NULL REFERENCES public.health_records(id) ON DELETE CASCADE,
  medicine_name TEXT NOT NULL,          -- e.g., "Dolo 650mg Tablet"
  generic_name TEXT,                    -- e.g., "Paracetamol"
  dosage_form VARCHAR(30),              -- 'Tablet', 'Syrup', 'Capsule', 'Injection'
  frequency VARCHAR(20) NOT NULL,       -- '1-0-1', '0-1-0', '1-1-1', 'SOS', 'OD', 'BD'
  timing VARCHAR(30) NOT NULL,          -- 'AFTER_FOOD', 'BEFORE_FOOD', 'WITH_FOOD'
  duration_days INT NOT NULL,
  instructions TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. Lab Observations (Normalized view for metric trend tracking like HbA1c, Cholesterol)
CREATE TABLE public.lab_observations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  record_id UUID NOT NULL REFERENCES public.health_records(id) ON DELETE CASCADE,
  patient_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  test_name TEXT NOT NULL,              -- e.g., "HbA1c", "Fasting Blood Sugar"
  loinc_code VARCHAR(20),               -- Standard LOINC code (e.g. 4548-4)
  value NUMERIC NOT NULL,
  unit VARCHAR(20) NOT NULL,            -- e.g., "%", "mg/dL"
  reference_low NUMERIC,
  reference_high NUMERIC,
  flag VARCHAR(10) CHECK (flag IN ('NORMAL', 'LOW', 'HIGH', 'CRITICAL')),
  observed_at TIMESTAMPTZ NOT NULL
);

-- Indexing for performance
CREATE INDEX idx_health_records_patient ON public.health_records(patient_id);
CREATE INDEX idx_lab_obs_patient_test ON public.lab_observations(patient_id, test_name);
CREATE INDEX idx_health_records_fhir ON public.health_records USING GIN(fhir_bundle);

-- 6. Strict Row-Level Security (RLS) Policies
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.care_contexts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.health_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.prescriptions_medications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lab_observations ENABLE ROW LEVEL SECURITY;

-- Note: Wrap auth.uid() in (SELECT auth.uid()) for optimal Postgres plan caching
CREATE POLICY "Users can view their own profile"
  ON public.profiles FOR SELECT
  TO authenticated
  USING (id = (SELECT auth.uid()));

CREATE POLICY "Users can update their own profile"
  ON public.profiles FOR UPDATE
  TO authenticated
  USING (id = (SELECT auth.uid()));

CREATE POLICY "Users can view their own health records"
  ON public.health_records FOR SELECT
  TO authenticated
  USING (patient_id = (SELECT auth.uid()));

CREATE POLICY "Users can insert their own health records"
  ON public.health_records FOR INSERT
  TO authenticated
  WITH CHECK (patient_id = (SELECT auth.uid()));

CREATE POLICY "Users can delete their own health records"
  ON public.health_records FOR DELETE
  TO authenticated
  USING (patient_id = (SELECT auth.uid()));

CREATE POLICY "Users can view their own lab results"
  ON public.lab_observations FOR SELECT
  TO authenticated
  USING (patient_id = (SELECT auth.uid()));

