  ON storage.objects FOR ALL
  TO authenticated
  USING (bucket_id = 'medical-documents' AND (storage.foldername(name))[1] = (SELECT auth.uid())::text)
  WITH CHECK (bucket_id = 'medical-documents' AND (storage.foldername(name))[1] = (SELECT auth.uid())::text);
